// Independently paraphrased history population, verified 2026-09-07.
const refs = {};
function ref(key, type, citation, url, locator, lineage = key) {
  refs[key] = { sourceId: `history-${key}`, lineageId: `history-${lineage}`, sourceType: type,
    citation, url, locator, accessedDate: '2026-09-07', accessStatus: 'anonymous_full_content',
    reuseStatus: 'publicly_accessible_citation_only',
    permissionBasis: 'Public content read anonymously; cited facts are independently paraphrased. No open reuse license is asserted.',
    supports: ['history'] };
}
