ref('tedlar60', M, 'DuPont. DuPont Celebrates 60th Anniversary of DuPont Tedlar. April 30, 2021.', 'https://www.dupont.com/content/dupont/amer/us/en/news/tedlar/2021/press-releases/20210430-60th-anniversary-of-dupont-tedlar.html', 'Historical chronology: 1901 monomer, 1942 polymer, 1947 patent, 1961 commercial film, Boeing 1963 and JPL 1986 qualification.');
