ref('hyosung-pk2015', M, 'Hyosung Chemical. History.', 'https://www.hyosungchemical.com/en/company/about/history', '2015, June: commencement of the POKETONE commercialization plant at Yongyeon, Ulsan.', 'hyosung');
ref('hyosung-pk-expo', M, 'Hyosung. Hyosung Introduces Cutting-Edge Materials Including Carbon Fiber in the 2015 Creative Economy Expo. November 26, 2015.', 'https://www.hyosung.com/en/newsroom/view/13202', 'Polyketone application discussion: vehicle components and gears for electronic products; material-program and product-development context.', 'hyosung');
add(88, 'Aliphatic polyketones developed through efforts to copolymerize carbon monoxide with olefins. A 1951 metal-catalyzed example produced low-melting oligomers; later nickel and palladium catalysts enabled useful alternating polymers. E. Drent and colleagues reported highly efficient diphosphine-palladium catalysts in 1991. Shell commercialized the carbon-monoxide/ethylene/propylene terpolymer as Carilon in 1996, then discontinued production in 2000. Hyosung revived industrial development in the following decade, announcing its polyketone in 2013 and starting its Ulsan commercial plant in June 2015 under the POKETONE name. Application development emphasized mechanical and industrial parts, including gears and vehicle components, together with food-contact and medical equipment. These milestones concern the alternating aliphatic engineering-plastic lineage; later research on non-alternating CO/ethylene polymers has a separate catalyst and application history.', 'pk-xiao2024', 'hyosung-pk2015', 'hyosung-pk-expo');

export default rows;
